 VALUES
('f407a818-46da-4ea6-8164-5088e185cf57'::uuid,'Weighted graph','Weighted graph','A graph in which each edge is assigned a numerical weight, such as distance or cost.','A route graph whose edges have associated distances or costs.','Hodder 9618 (Watson & Williams, 2019), §18.1.1, p.426; Cambridge 9618 Syllabus 2027–2029, §18.1, p.36 (purpose and structure of graphs; A*/Dijkstra searches); PDF:9618_Chapter_18.pdf; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (Watson & Williams, 2019), §18.1.1, p.426; chapter detail; PDF:9618_Chapter_18.pdf; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-'),
('f1b4ee38-32e5-423b-acfc-af0315091762'::uuid,'Edge weight','Edge weight','The numerical distance, cost or time assigned to a connection between two vertices in a graph.','The numerical distance or cost shown between connected vertices.','Hodder 9618 (Watson & Williams, 2019), §18.1.1, p.426; Cambridge 9618 Syllabus 2027–2029, §18.1, p.36 (purpose and structure of graphs; A*/Dijkstra searches); PDF:9618_Chapter_18.pdf; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (Watson & Williams, 2019), §18.1.1, p.426; chapter detail; PDF:9618_Chapter_18.pdf; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-'),
('0fad4245-958b-4f33-9ccc-181cb2839bd8'::uuid,'Dijkstra versus A*','Dijkstra versus A*','Dijkstra selects the unvisited vertex with the smallest known distance; A* also uses a heuristic estimate of the remaining cost to the destination.','Dijkstra explores by shortest known distance whereas A* also uses a heuristic estimate to guide its direction.','Hodder 9618 (Watson & Williams, 2019), §18.1.2, pp.429–431; Cambridge 9618 Syllabus 2027–2029, §18.1, p.36 (use A* and Dijkstra to search graphs); PDF:9618_Chapter_18.pdf; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (Watson & Williams, 2019), §18.1.2, p.429; chapter detail; PDF:9618_Chapter_18.pdf; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-'),
('b9970d9f-a552-4329-b4e7-5043464eac4d'::uuid,'A* evaluation function','f(n) = g(n) + h(n)','A* scores a node using f(n) = g(n) + h(n), where g(n) is the cost from the start to that node and h(n) estimates the remaining cost to the goal.','The A* evaluation rule used in the chapter to compare candidate moves.','Hodder 9618 (Watson & Williams, 2019), §18.1.2, p.431; Cambridge 9618 Syllabus 2027–2029, §18.1, p.36 (use A* to search graphs); PDF:9618_Chapter_18.pdf; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (Watson & Williams, 2019), §18.1.2, p.431; chapter detail; PDF:9618_Chapter_18.pdf; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-'),
('9edebb0f-beeb-42fc-827d-4e642b300afb'::uuid,'Machine learning categories','Learning type comparison','Supervised learning uses labelled input/output examples; unsupervised learning finds patterns without known target answers; reinforcement learning improves actions using rewards and penalties.','Contrasting known-output training, hidden-pattern detection, trial-and-error rewards and limited labelling.','Hodder 9618 (Watson & Williams, 2019), §18.2.2, pp.438–439; Cambridge 9618 Syllabus 2027–2029, §18.1, p.36 (machine-learning categories, including supervised and unsupervised learning, and reinforcement learning); PDF:9618_Chapter_18.pdf; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (Watson & Williams, 2019), §18.2.2, p.439; chapter detail; PDF:9618_Chapter_18.pdf; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-'),
('9cae3e08-4415-41e8-8daa-fb0c7df62c98'::uuid,'Machine learning versus deep learning','Machine learning versus deep learning','Machine learning includes methods that learn patterns from data; deep learning is a form of machine learning that uses multi-layer artificial neural networks and can learn useful features from the data itself.','The textbook''s comparison of models using engineered features and modular steps against layered neural-network approaches.','Hodder 9618 (Watson & Williams, 2019), §18.2.3–18.2.4, pp.442–443; Cambridge 9618 Syllabus 2027–2029, §18.1, p.36 (machine learning, deep learning and neural networks); PDF:9618_Chapter_18.pdf; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (Watson & Williams, 2019), §18.2.4, p.443; chapter detail; PDF:9618_Chapter_18.pdf; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-'),
('d7a75b22-5ce7-4ac3-b7da-004d82814c93'::uuid,'Automatic feature learning','Automatic feature learning','A deep-learning model can learn useful features directly from training data instead of requiring people to define every feature in advance.','Letting a deep-learning model discover relevant features from data without manually specifying all of them.','Hodder 9618 (Watson & Williams, 2019), §18.2.4, p.443; Cambridge 9618 Syllabus 2027–2029, §18.1, p.36 (deep learning and artificial neural networks); PDF:9618_Chapter_18.pdf; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-','Hodder 9618 (Watson & Williams, 2019), §18.2.4, p.443; chapter detail; PDF:9618_Chapter_18.pdf; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-')
)
UPDATE public.glossary_terms AS g
SET term=c.old_term,
    definition_en=c.old_definition,
    source_ref=c.old_source,
    definition_evidence_status='supplementary_manual_review_required',
    is_glossary_visible=false
FROM changes AS c
WHERE g.id=c.id
  AND g.term=c.new_term
  AND g.definition_en=c.new_definition
  AND g.source_ref=c.new_source
  AND g.definition_evidence_status='supplementary_targeted_verified'
  AND g.is_glossary_visible=true
RETURNING g.id,g.term,g.definition_evidence_status,g.is_glossary_visible;
